fun gcd(a: Int, b: Int): Int = if (b == 0) a else gcd(b, a % b)

fun gcdIterative(a: Long, b: Long): Long {
    var x = a
    var y = b
    while (y != 0L) {
        val t = x % y
        x = y
        y = t
    }
    return x
}

fun lcm(a: Int, b: Int): Long = (a / gcd(a, b)).toLong() * b      // divide first to reduce overflow
// Time: O(log min(a, b))   Space: O(1)

fun isPrime(n: Int): Boolean {
    if (n < 2) return false
    if (n < 4) return true                    // 2 and 3
    if (n % 2 == 0) return false
    var i = 3
    while (i.toLong() * i <= n) {            // only test up to sqrt(n)
        if (n % i == 0) return false
        i += 2                                // skip even divisors
    }
    return true
}
// Time: O(sqrt(n))   Space: O(1)

fun sieve(n: Int): BooleanArray {
    val isPrime = BooleanArray(n + 1) { true }
    if (n >= 0) isPrime[0] = false
    if (n >= 1) isPrime[1] = false
    var i = 2
    while (i.toLong() * i <= n) {
        if (isPrime[i]) {
            var j = i * i                      // smaller multiples were crossed out by smaller primes
            while (j <= n) {
                isPrime[j] = false
                j += i
            }
        }
        i++
    }
    return isPrime
}
// Time: O(n log log n)   Space: O(n)

fun primeFactors(n: Int): Map<Int, Int> {           // prime -> exponent
    var x = n
    val factors = LinkedHashMap<Int, Int>()
    var p = 2
    while (p.toLong() * p <= x) {
        while (x % p == 0) {
            factors[p] = (factors[p] ?: 0) + 1
            x /= p
        }
        p++
    }
    if (x > 1) factors[x] = (factors[x] ?: 0) + 1      // what remains is a prime larger than sqrt
    return factors
}
// Time: O(sqrt(n))

// For many queries: smallest prime factor table
fun smallestPrimeFactors(n: Int): IntArray {
    val spf = IntArray(n + 1) { it }
    var i = 2
    while (i.toLong() * i <= n) {
        if (spf[i] == i) {
            var j = i * i
            while (j <= n) {
                if (spf[j] == j) spf[j] = i
                j += i
            }
        }
        i++
    }
    return spf
}

fun factorize(x: Int, spf: IntArray): Map<Int, Int> {
    var n = x
    val factors = HashMap<Int, Int>()
    while (n > 1) {
        val p = spf[n]
        factors[p] = (factors[p] ?: 0) + 1
        n /= p
    }
    return factors
}
// Build: O(n log log n)   Each factorization: O(log n)

fun powMod(base: Long, exp: Long, mod: Long): Long {
    var result = 1L
    var b = base % mod
    var e = exp
    while (e > 0) {
        if ((e and 1L) == 1L) result = result * b % mod    // use this power of b
        b = b * b % mod                                    // b, b², b⁴, b⁸, ...
        e = e shr 1
    }
    return result
}
// Time: O(log exp)   Space: O(1)
// Requires mod up to about 3 * 10^9 so that b * b fits in a Long

const val MOD = 1_000_000_007L

fun modInverse(a: Long, mod: Long = MOD): Long = powMod(a, mod - 2, mod)    // Fermat's little theorem

class Combinatorics(maxN: Int, private val mod: Long = MOD) {
    private val fact = LongArray(maxN + 1)
    private val invFact = LongArray(maxN + 1)

    init {
        fact[0] = 1
        for (i in 1..maxN) fact[i] = fact[i - 1] * i % mod
        invFact[maxN] = powMod(fact[maxN], mod - 2, mod)
        for (i in maxN downTo 1) invFact[i - 1] = invFact[i] * i % mod
    }

    fun nCr(n: Int, r: Int): Long {
        if (r < 0 || r > n) return 0
        return fact[n] * invFact[r] % mod * invFact[n - r] % mod
    }
}
// Build: O(maxN)   Each nCr: O(1)

fun nCrExact(n: Int, r: Int): Long {
    val k = minOf(r, n - r)                    // C(n, r) = C(n, n - r)
    var result = 1L
    for (i in 1..k) {
        result = result * (n - k + i) / i      // stays an integer at every step
    }
    return result
}
// Time: O(min(r, n - r))   Fits in Long for results up to about 9 * 10^18

// Returns (g, x, y) such that a * x + b * y = g = gcd(a, b)
fun extGcd(a: Long, b: Long): Triple<Long, Long, Long> {
    if (b == 0L) return Triple(a, 1L, 0L)
    val (g, x1, y1) = extGcd(b, a % b)
    return Triple(g, y1, x1 - (a / b) * y1)
}

fun modInverseAny(a: Long, m: Long): Long? {
    val (g, x, _) = extGcd(a, m)
    return if (g != 1L) null else ((x % m) + m) % m       // an inverse exists only when gcd(a, m) = 1
}
// Time: O(log m)

fun digitsOf(n: Int): List<Int> {
    if (n == 0) return listOf(0)
    var x = n
    val digits = ArrayList<Int>()
    while (x > 0) {
        digits.add(x % 10)                     // last digit
        x /= 10                                // drop the last digit
    }
    digits.reverse()
    return digits
}

fun toBase(n: Int, base: Int): String {
    if (n == 0) return "0"
    var x = n
    val sb = StringBuilder()
    while (x > 0) {
        sb.append(Character.forDigit(x % base, base))
        x /= base
    }
    return sb.reverse().toString()
}
// Built-ins: Integer.toString(n, base) and Integer.parseInt(s, base)

fun safeExamples() {
    val a = Int.MAX_VALUE
    // 1. Promote to Long before multiplying
    val product = a.toLong() * a.toLong()

    // 2. Throw on overflow instead of silently wrapping
    try {
        Math.addExact(a, 1)
    } catch (e: ArithmeticException) {
        println("overflow detected")
    }

    // 3. Check before the operation
    fun addWouldOverflow(x: Int, y: Int): Boolean =
        (y > 0 && x > Int.MAX_VALUE - y) || (y < 0 && x < Int.MIN_VALUE - y)

    // 4. Math.abs(Int.MIN_VALUE) is still negative: use Long
    val absMin = Math.abs(Int.MIN_VALUE.toLong())
}

fun countPrimes(n: Int): Int {
    if (n < 3) return 0
    val composite = BooleanArray(n)
    var count = 0
    for (i in 2 until n) {
        if (!composite[i]) {
            count++
            var j = i.toLong() * i             // start at i * i, use Long to avoid overflow
            while (j < n) {
                composite[j.toInt()] = true
                j += i
            }
        }
    }
    return count
}
// Time: O(n log log n)   Space: O(n)

fun myPow(x: Double, n: Int): Double {
    var base = x
    var e = n.toLong()                         // Long so that -Int.MIN_VALUE does not overflow
    if (e < 0) {
        base = 1 / base
        e = -e
    }
    var result = 1.0
    while (e > 0) {
        if ((e and 1L) == 1L) result *= base
        base *= base
        e = e shr 1
    }
    return result
}
// Time: O(log n)   Space: O(1)

fun mySqrt(x: Int): Int {
    if (x < 2) return x
    var r = x.toLong()
    while (r * r > x) {
        r = (r + x / r) / 2                    // average r with x / r, converges quickly from above
    }
    return r.toInt()
}
// Time: O(log x)   Space: O(1)
// Binary search on the answer also works, see the Binary Search topic

fun reverse(x: Int): Int {
    var n = x
    var rev = 0
    while (n != 0) {
        val digit = n % 10
        n /= 10
        // check before rev * 10 + digit would overflow
        if (rev > Int.MAX_VALUE / 10 || (rev == Int.MAX_VALUE / 10 && digit > 7)) return 0
        if (rev < Int.MIN_VALUE / 10 || (rev == Int.MIN_VALUE / 10 && digit < -8)) return 0
        rev = rev * 10 + digit
    }
    return rev
}
// Time: O(digits)   Space: O(1)

fun isPalindrome(x: Int): Boolean {
    if (x < 0 || (x % 10 == 0 && x != 0)) return false
    var n = x
    var rev = 0
    while (n > rev) {                          // reverse only half the digits
        rev = rev * 10 + n % 10
        n /= 10
    }
    return n == rev || n == rev / 10           // even or odd number of digits
}
// Time: O(digits)   Space: O(1)

fun trailingZeroes(n: Int): Int {
    var x = n
    var count = 0
    while (x > 0) {
        x /= 5                                 // multiples of 5, then 25, then 125, ...
        count += x
    }
    return count
}
// Time: O(log n)   Space: O(1)
// Zeros come from pairs of 2 and 5, and there are always more 2s than 5s

fun convertToTitle(columnNumber: Int): String {
    var n = columnNumber
    val sb = StringBuilder()
    while (n > 0) {
        n--                                    // shift to 0-based: A = 0, ..., Z = 25
        sb.append('A' + n % 26)
        n /= 26
    }
    return sb.reverse().toString()
}

fun titleToNumber(s: String): Int {
    var result = 0
    for (c in s) result = result * 26 + (c - 'A' + 1)
    return result
}
// Time: O(log26 n)   Space: O(1)

fun addStrings(a: String, b: String): String {
    var i = a.length - 1
    var j = b.length - 1
    var carry = 0
    val sb = StringBuilder()
    while (i >= 0 || j >= 0 || carry > 0) {
        val x = if (i >= 0) a[i--] - '0' else 0
        val y = if (j >= 0) b[j--] - '0' else 0
        val sum = x + y + carry
        sb.append(sum % 10)
        carry = sum / 10
    }
    return sb.reverse().toString()
}

fun multiply(num1: String, num2: String): String {
    if (num1 == "0" || num2 == "0") return "0"
    val res = IntArray(num1.length + num2.length)
    for (i in num1.indices.reversed()) {
        for (j in num2.indices.reversed()) {
            val prod = (num1[i] - '0') * (num2[j] - '0')
            val sum = prod + res[i + j + 1]
            res[i + j + 1] = sum % 10
            res[i + j] += sum / 10
        }
    }
    val sb = StringBuilder()
    for (d in res) {
        if (!(sb.isEmpty() && d == 0)) sb.append(d)     // skip leading zeros
    }
    return sb.toString()
}
// addStrings: O(n + m)   multiply: O(n * m)

fun fractionToDecimal(numerator: Int, denominator: Int): String {
    if (numerator == 0) return "0"
    val sb = StringBuilder()
    if ((numerator < 0) != (denominator < 0)) sb.append('-')
    val num = Math.abs(numerator.toLong())
    val den = Math.abs(denominator.toLong())
    sb.append(num / den)
    var rem = num % den
    if (rem == 0L) return sb.toString()
    sb.append('.')
    val seen = HashMap<Long, Int>()                    // remainder -> position in the output
    while (rem != 0L) {
        if (rem in seen) {                             // a repeated remainder means a repeating cycle
            sb.insert(seen[rem]!!, "(")
            sb.append(')')
            break
        }
        seen[rem] = sb.length
        rem *= 10
        sb.append(rem / den)
        rem %= den
    }
    return sb.toString()
}
// Time: O(den)   Space: O(den)

fun gcdOfStrings(str1: String, str2: String): String {
    if (str1 + str2 != str2 + str1) return ""          // no common building block
    val g = gcd(str1.length, str2.length)
    return str1.substring(0, g)
}
// Time: O(n + m)   Space: O(n + m)

fun canMeasureWater(x: Int, y: Int, target: Int): Boolean {
    if (x + y < target) return false
    if (x == 0 || y == 0) return target == 0 || x + y == target
    return target % gcd(x, y) == 0                     // any multiple of gcd(x, y) is reachable
}
// Time: O(log min(x, y))   Space: O(1)

fun maxPoints(points: Array<IntArray>): Int {
    val n = points.size
    if (n <= 2) return n
    var best = 2
    for (i in 0 until n) {
        val slopes = HashMap<String, Int>()
        var localBest = 0
        for (j in i + 1 until n) {
            var dx = points[j][0] - points[i][0]
            var dy = points[j][1] - points[i][1]
            val g = gcd(Math.abs(dx), Math.abs(dy))
            dx /= g                                    // reduce the slope to lowest terms
            dy /= g
            if (dx < 0 || (dx == 0 && dy < 0)) {       // normalize the sign so equal slopes match
                dx = -dx
                dy = -dy
            }
            val key = "$dx/$dy"
            val c = (slopes[key] ?: 0) + 1
            slopes[key] = c
            localBest = maxOf(localBest, c)
        }
        best = maxOf(best, localBest + 1)              // plus the anchor point
    }
    return best
}
// Time: O(n² log C)   Space: O(n)
// Using floating-point slopes can give wrong results, a reduced fraction is exact

fun uniquePaths(m: Int, n: Int): Int {
    // choose which (m - 1) of the (m + n - 2) moves go down
    return nCrExact(m + n - 2, m - 1).toInt()
}
// Time: O(min(m, n))   Space: O(1)

fun lastRemaining(n: Int, k: Int): Int {
    var pos = 0                                // survivor index (0-based) in a circle of size 1
    for (size in 2..n) {
        pos = (pos + k) % size                 // re-index after the next person is removed
    }
    return pos + 1                             // 1-based position
}
// Time: O(n)   Space: O(1)

fun divide(dividend: Int, divisor: Int): Int {
    if (dividend == Int.MIN_VALUE && divisor == -1) return Int.MAX_VALUE
    val negative = (dividend < 0) != (divisor < 0)
    var a = Math.abs(dividend.toLong())
    val b = Math.abs(divisor.toLong())
    var result = 0L
    while (a >= b) {
        var temp = b
        var multiple = 1L
        while (a >= (temp shl 1)) {            // double the divisor while it still fits
            temp = temp shl 1
            multiple = multiple shl 1
        }
        a -= temp
        result += multiple
    }
    return if (negative) (-result).toInt() else result.toInt()
}
// Time: O(log² n)   Space: O(1)

fun superPow(a: Int, b: IntArray): Int {
    val mod = 1337L
    var result = 1L
    var base = a.toLong() % mod
    for (i in b.indices.reversed()) {                  // process digits from the least significant
        result = result * powMod(base, b[i].toLong(), mod) % mod
        base = powMod(base, 10, mod)                   // base becomes base^10 for the next digit
    }
    return result.toInt()
}
// Time: O(len(b) * log 10)   Space: O(1)

fun distinctPrimeFactorCounts(nums: IntArray): IntArray {
    val maxVal = nums.maxOrNull() ?: return IntArray(0)
    val spf = smallestPrimeFactors(maxVal)
    return IntArray(nums.size) { idx ->
        factorize(nums[idx], spf).size                 // number of distinct primes
    }
}
// Build: O(M log log M)   Each number: O(log M)
